func interpolate(points, x) =
  {
    local pt1 = points[1]
    local pt2 = points[points.listLen()]
    for (i: 1 .. points.listLen() - 1 step 1) {
      if (points[i][1] <= x && points[i + 1][1] >= x) {
        pt1 = points[i]
        pt2 = points[i + 1]
        break
      }
    }
    local t = if (pt2[1] == pt1[1]) {
      0
    } else {
      (x - pt1[1]) / (pt2[1] - pt1[1])
    }
    pt1[2] + (pt2[2] - pt1[2]) * t
  }
