func evalRPN(tokens) =
  {
    local stack = []
    for (tok in tokens) {
      if (tok === "+") {
        local b = stack[stack.listLen()]
        stack.remove(stack.listLen())
        local a = stack[stack.listLen()]
        stack.remove(stack.listLen())
        stack.add(a + b)
      } else if (tok === "-") {
        local b = stack[stack.listLen()]
        stack.remove(stack.listLen())
        local a = stack[stack.listLen()]
        stack.remove(stack.listLen())
        stack.add(a - b)
      } else if (tok === "*") {
        local b = stack[stack.listLen()]
        stack.remove(stack.listLen())
        local a = stack[stack.listLen()]
        stack.remove(stack.listLen())
        stack.add(a * b)
      } else if (tok === "/") {
        local b = stack[stack.listLen()]
        stack.remove(stack.listLen())
        local a = stack[stack.listLen()]
        stack.remove(stack.listLen())
        stack.add(a / b)
      } else {
        stack.add(tok)
      }
    }
    stack[1]
  }

println(evalRPN([3, 4, "+", 2, "*", 7, "/"]))
