func floodFill(board, row, col, oldVal, newVal) =
  {
    if (board[row][col] != oldVal) {
      board
    } else {
      local stack = [[row, col]]
      local rows = board.listLen()
      local cols = board[1].listLen()
      while (stack.listLen() > 0) {
        local cur = stack[stack.listLen()]
        stack.remove(stack.listLen())
        local r = cur[1]
        local c = cur[2]
        if (r >= 1 && r <= rows && c >= 1 && c <= cols && board[r][c] == oldVal) {
          board[r][c] = newVal
          stack.add([r + 1, c])
          stack.add([r - 1, c])
          stack.add([r, c + 1])
          stack.add([r, c - 1])
        }
      }
      board
    }
  }

