func muller(f_name, x0, x1, x2, maxIter) =
  {
    local p0 = x0
    local p1 = x1
    local p2 = x2
    local root_m = p2
    local iter_m = 0
    while (iter_m < maxIter) {
      local f0 = p0 ^ 3 - p0 - 2
      local f1 = p1 ^ 3 - p1 - 2
      local f2 = p2 ^ 3 - p2 - 2
      local h1 = p1 - p0
      local h2 = p2 - p1
      local d1 = (f1 - f0) / h1
      local d2 = (f2 - f1) / h2
      local a_m = (d2 - d1) / (h2 + h1)
      local b_m = a_m * h2 + d2
      local c_m = f2
      local disc = b_m ^ 2 - 4 * a_m * c_m
      local denom = if (abs(b_m + sqrt(abs(disc))) > abs(b_m - sqrt(abs(disc)))) {
        b_m + sqrt(abs(disc))
      } else {
        b_m - sqrt(abs(disc))
      }
      if (abs(denom) < 0.000000000000001) {
        iter_m = maxIter
      }
      local dx = -2 * c_m / denom
      root_m = p2 + dx
      p0 = p1
      p1 = p2
      p2 = root_m
      iter_m = iter_m + 1
      if (abs(dx) < 0.00000001) {
        iter_m = maxIter
      }
    }
    root_m
  }

println("Muller root: " _ muller("cubic", 0, 1, 2, 50))
