func excerptAround(text, keyword, radius) =
  {
    local idx = 1
    local klen = keyword.textLen()
    local tlen = text.textLen()
    local found = false
    local pos = 1
    while (idx <= tlen - klen + 1 && (!found)) {
      if (text.segment(idx, klen) === keyword) {
        found = true
        pos = idx
      }
      idx = idx + 1
    }
    if (!found) {
      ""
    } else {
      local start = if (pos - radius < 1) {
        1
      } else {
        pos - radius
      }
      local len = 2 * radius + klen
      text.segment(start, len)
    }
  }

