func floodFill(grid, r, c, newVal) =
  {
    local target = grid[r][c]
    if (target == newVal) {
      grid
    } else {
      local rows = grid.listLen()
      local cols = grid[1].listLen()
      local stack = [[r, c]]
      while (stack.listLen() > 0) {
        local cur = stack[stack.listLen()]
        stack.remove(stack.listLen())
        local cr = cur[1]
        local cc = cur[2]
        if (cr >= 1 && cr <= rows && cc >= 1 && cc <= cols && grid[cr][cc] == target) {
          grid[cr][cc] = newVal
          stack.add([cr + 1, cc])
          stack.add([cr - 1, cc])
          stack.add([cr, cc + 1])
          stack.add([cr, cc - 1])
        }
      }
      grid
    }
  }

