func jumpSearch(lst, target) =
  {
    local n = lst.listLen()
    local stepVar = floor(sqrt(n))
    local prev = 1
    local curr = stepVar
    while (curr <= n && lst[curr] < target) {
      prev = curr
      curr = curr + stepVar
    }
    local result = -1
    for (i: prev .. min(curr, n) step 1) {
      if (lst[i] == target) {
        result = i
      }
    }
